using System.IO;
using Microsoft.Data.Sqlite;
namespace Ansary;
public sealed record IndexedHit(string Path,int Index,string Text,long Length,long Ticks);
public sealed class DocumentStore {
 readonly object gate=new();readonly string database;readonly Dictionary<string,(DocumentSnapshot Doc,long Used,long Cost)> memory=new(StringComparer.OrdinalIgnoreCase);long used,clock;const long Limit=64L*1024*1024;
 public DocumentStore(string? location=null){database=location??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ElansaryWordLibrary","paragraph-index-v1.db");}
 SqliteConnection Open(){Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(database))!);var db=new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=database,Pooling=false}.ToString());try{db.Open();using var c=db.CreateCommand();c.CommandText="PRAGMA foreign_keys=ON; CREATE TABLE IF NOT EXISTS files(id INTEGER PRIMARY KEY,path TEXT NOT NULL UNIQUE COLLATE NOCASE,size INTEGER NOT NULL,ticks INTEGER NOT NULL); CREATE TABLE IF NOT EXISTS paragraphs(id INTEGER PRIMARY KEY,file_id INTEGER NOT NULL REFERENCES files(id),num INTEGER NOT NULL,raw TEXT NOT NULL,folded TEXT NOT NULL); CREATE INDEX IF NOT EXISTS paragraph_file ON paragraphs(file_id,num); CREATE VIRTUAL TABLE IF NOT EXISTS search USING fts5(folded,content='paragraphs',content_rowid='id',tokenize='trigram case_sensitive 1'); CREATE TRIGGER IF NOT EXISTS para_ai AFTER INSERT ON paragraphs BEGIN INSERT INTO search(rowid,folded) VALUES(new.id,new.folded); END; CREATE TRIGGER IF NOT EXISTS para_ad AFTER DELETE ON paragraphs BEGIN INSERT INTO search(search,rowid,folded) VALUES('delete',old.id,old.folded); END;";c.ExecuteNonQuery();return db;}catch{db.Dispose();throw;}}
 (long Id,long Size,long Ticks,string Path) Ensure(SqliteConnection db,string path,CancellationToken token){token.ThrowIfCancellationRequested();path=Path.GetFullPath(path);var info=new FileInfo(path);long size=info.Length,ticks=info.LastWriteTimeUtc.Ticks,id=0;using(var c=db.CreateCommand()){c.CommandText="SELECT id,size,ticks FROM files WHERE path=$p";c.Parameters.AddWithValue("$p",path);using var r=c.ExecuteReader();if(r.Read()){id=r.GetInt64(0);if(r.GetInt64(1)==size&&r.GetInt64(2)==ticks)return(id,size,ticks,path);}}
  var text=Core.Read(path);token.ThrowIfCancellationRequested();var after=new FileInfo(path);if(after.Length!=size||after.LastWriteTimeUtc.Ticks!=ticks)throw new IOException("تغيّر الملف أثناء الفهرسة؛ أعد المحاولة");using var tx=db.BeginTransaction();using(var c=db.CreateCommand()){c.Transaction=tx;c.CommandText="INSERT INTO files(path,size,ticks) VALUES($p,$s,$t) ON CONFLICT(path) DO UPDATE SET size=excluded.size,ticks=excluded.ticks RETURNING id";c.Parameters.AddWithValue("$p",path);c.Parameters.AddWithValue("$s",size);c.Parameters.AddWithValue("$t",ticks);id=Convert.ToInt64(c.ExecuteScalar());}using(var c=db.CreateCommand()){c.Transaction=tx;c.CommandText="DELETE FROM paragraphs WHERE file_id=$id";c.Parameters.AddWithValue("$id",id);c.ExecuteNonQuery();}using(var c=db.CreateCommand()){c.Transaction=tx;c.CommandText="INSERT INTO paragraphs(file_id,num,raw,folded) VALUES($id,$n,$raw,$fold)";c.Parameters.AddWithValue("$id",id);var n=c.Parameters.Add("$n",SqliteType.Integer);var raw=c.Parameters.Add("$raw",SqliteType.Text);var fold=c.Parameters.Add("$fold",SqliteType.Text);for(int i=0;i<text.Length;i++){token.ThrowIfCancellationRequested();n.Value=i;raw.Value=text[i];fold.Value=text[i].ToUpperInvariant();c.ExecuteNonQuery();}}token.ThrowIfCancellationRequested();tx.Commit();Remember(new DocumentSnapshot(path,size,ticks,text));return(id,size,ticks,path);
 }
 void Remember(DocumentSnapshot doc){if(memory.Remove(doc.Path,out var old))used-=old.Cost;long cost=doc.Paragraphs.Sum(s=>(long)s.Length*2+32)+doc.Paragraphs.LongLength*8;if(cost>Limit)return;while(used+cost>Limit&&memory.Count>0){var oldest=memory.MinBy(e=>e.Value.Used);used-=oldest.Value.Cost;memory.Remove(oldest.Key);}memory[doc.Path]=(doc,++clock,cost);used+=cost;}
 public DocumentSnapshot Get(string path){lock(gate){using var db=Open();var f=Ensure(db,path,CancellationToken.None);if(memory.TryGetValue(f.Path,out var m)&&m.Doc.Length==f.Size&&m.Doc.Ticks==f.Ticks){memory[f.Path]=(m.Doc,++clock,m.Cost);return m.Doc;}using var c=db.CreateCommand();c.CommandText="SELECT raw FROM paragraphs WHERE file_id=$id ORDER BY num";c.Parameters.AddWithValue("$id",f.Id);var text=new List<string>();using(var r=c.ExecuteReader())while(r.Read())text.Add(r.GetString(0));var doc=new DocumentSnapshot(f.Path,f.Size,f.Ticks,text.ToArray());Remember(doc);return doc;}}
 public List<IndexedHit> Search(string path,string[] words,CancellationToken token){lock(gate){using var db=Open();var f=Ensure(db,path,token);var eligible=words.Where(w=>w.Length>=3&&w.All(ch=>(ch>=' '&&ch<='~')||(ch>='\u0600'&&ch<='\u06ff'))).ToArray();var hits=new List<IndexedHit>();using var c=db.CreateCommand();c.CommandText=eligible.Length==0?"SELECT num,raw FROM paragraphs WHERE file_id=$id ORDER BY num":"SELECT p.num,p.raw FROM search JOIN paragraphs p ON p.id=search.rowid WHERE search MATCH $q AND p.file_id=$id ORDER BY p.num";c.Parameters.AddWithValue("$id",f.Id);if(eligible.Length>0)c.Parameters.AddWithValue("$q",string.Join(" AND ",eligible.Select(w=>"\""+w.ToUpperInvariant().Replace("\"","\"\"")+"\"")));using var r=c.ExecuteReader();while(r.Read()){token.ThrowIfCancellationRequested();string text=r.GetString(1);if(Core.Match(text,words))hits.Add(new IndexedHit(f.Path,r.GetInt32(0),text,f.Size,f.Ticks));}return hits;}}
 public static void Verify(){string dir=Path.Combine(Path.GetTempPath(),"AnsaryIndex-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{string file=Path.Combine(dir,"test.docx");using(var z=System.IO.Compression.ZipFile.Open(file,System.IO.Compression.ZipArchiveMode.Create)){var entry=z.CreateEntry("word/document.xml");using var w=new StreamWriter(entry.Open());w.Write("<w:document xmlns:w='http://schemas.openxmlformats.org/wordprocessingml/2006/main'><w:body><w:p><w:r><w:t>بحث عربي سريع في المكتبة ABCDE</w:t></w:r></w:p><w:p><w:r><w:t>النتائج هنا في المكتبة</w:t></w:r></w:p></w:body></w:document>");}var store=new DocumentStore(Path.Combine(dir,"test.db"));foreach(string query in new[]{"بحث سريع","في","\"في المكتبة\"","bcd","غيرموجود","عربي بحث"}){var terms=Core.Terms(query);var expected=Core.Read(file).Select((t,i)=>(t,i)).Where(x=>Core.Match(x.t,terms)).Select(x=>x.i).ToArray();for(int pass=0;pass<2;pass++)if(!expected.SequenceEqual(store.Search(file,terms,CancellationToken.None).Select(h=>h.Index)))throw new InvalidDataException("FTS search parity failed: "+query);}if(store.Get(file).Paragraphs.Length!=2)throw new InvalidDataException("Indexed document read failed");}finally{Directory.Delete(dir,true);}}
}
